import json
from pathlib import Path

data=json.loads(Path('benchmark/source_data.json').read_text())
lcoe=data['lcoe_trends']['data']
foss=data['fossil_fuel_lcoe_range']['data']

years=list(range(2010,2025))

# build fossil dict by year
foss_by_year={row['year']:row for row in foss}

# linear interpolation helper for a given field
fields=['gas_ccgt_low','gas_ccgt_high','coal_low','coal_high']

# known years sorted
ky=sorted(foss_by_year)

def interp(field, y):
    if y in foss_by_year:
        return foss_by_year[y][field]
    # find surrounding known years
    y0=max([t for t in ky if t<y])
    y1=min([t for t in ky if t>y])
    v0=foss_by_year[y0][field]
    v1=foss_by_year[y1][field]
    return v0 + (v1-v0)*(y-y0)/(y1-y0)

foss_annual=[]
for y in years:
    row={'year':y}
    for f in fields:
        row[f]=interp(f,y)
    row['foss_low']=min(row['gas_ccgt_low'],row['coal_low'])
    row['foss_high']=max(row['gas_ccgt_high'],row['coal_high'])
    foss_annual.append(row)

foss_annual_by_year={r['year']:r for r in foss_annual}

for tech in ['solar_pv','onshore_wind']:
    first_below_low=None
    first_below_high=None
    for r in lcoe:
        y=r['year']
        if first_below_low is None and r[tech] < foss_annual_by_year[y]['foss_low']:
            first_below_low=y
        if first_below_high is None and r[tech] < foss_annual_by_year[y]['foss_high']:
            first_below_high=y
    print(tech,'first year below fossil low:',first_below_low)
    print(tech,'first year below fossil high:',first_below_high)
PY"}
